// Normaliza el payload del proveedor de WhatsApp al formato del asistente.
// EJEMPLO para Twilio WhatsApp (ajustar según proveedor):
//   body.From  -> threadId
//   body.Body  -> text
//   body.MediaUrl0 -> imagen (descargarla en un nodo HTTP previo si aplica)
const body = $input.first().json.body ?? $input.first().json;
return [{
  json: {
    threadId: String(body.From ?? body.from ?? 'desconocido').replace(/[^0-9+a-zA-Z:]/g, ''),
    text: body.Body ?? body.text ?? null,
    imageBase64: body.imageBase64 ?? null,
    imageMediaType: body.imageMediaType ?? null,
  },
}];
